/**
 * Publish source-derived contract references without maintaining a second API model.
 *
 * Deno owns public re-export resolution, type notation and declaration comments.
 * Markdown keeps its readable declaration output; JSON retains the complete type
 * and comment structure, including overloads and method type parameters. Check
 * mode compares regenerated bytes and never writes the reference files.
 * @module
 */
import { relative, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { stripVTControlCharacters } from 'node:util';
import { parse } from '@std/jsonc';

/** Manifest-owned package identity and public source subpaths. */
interface PackageType {
	readonly name: string;
	readonly version: string;
	readonly exports: Readonly<Record<string, string>>;
}

/** One inspected package; directory names never determine public import names. */
interface MemberType {
	readonly directory: string;
	readonly manifest: PackageType;
}

/** Deno's versioned JSON envelope; declaration structure is preserved verbatim. */
interface DocumentType {
	readonly version: number;
	readonly nodes: Readonly<
		Record<string, {
			readonly symbols: readonly { readonly name: string }[];
			readonly imports?: readonly { readonly src: string; readonly importedName?: string }[];
		}>
	>;
}

/** Reject malformed manifests before selecting modules or publishing references. */
function member(value: unknown): PackageType {
	if (value === null || typeof value !== 'object' || Array.isArray(value)) {
		throw new TypeError('A package manifest must be an object.');
	}
	const fields = value as Record<string, unknown>;
	const exports = fields.exports;
	if (
		typeof fields.name !== 'string' || typeof fields.version !== 'string' ||
		exports === null || typeof exports !== 'object' || Array.isArray(exports)
	) throw new TypeError('A package needs its name, version and public exports.');
	const entries = Object.entries(exports).map(([key, path]) => {
		if (typeof path !== 'string' || !path.startsWith('./') || !path.endsWith('.ts')) {
			throw new TypeError(`Public export ${key} must identify a local TypeScript module.`);
		}
		return [key, path] as const;
	});
	return { name: fields.name, version: fields.version, exports: Object.fromEntries(entries) };
}

/** Invoke the installed Deno renderer and fail before publishing incomplete output. */
async function doc(args: readonly string[]): Promise<string> {
	const result = await new Deno.Command(Deno.execPath(), {
		args: ['doc', ...args],
		env: { NO_COLOR: '1', FORCE_COLOR: '0' },
		stdout: 'piped',
		stderr: 'piped',
	}).output();
	if (!result.success) throw new Error(new TextDecoder().decode(result.stderr));
	return stripVTControlCharacters(new TextDecoder().decode(result.stdout));
}

/** Keep generated paths independent of a host checkout or an isolated runner. */
function portable(value: unknown, root: string): unknown {
	if (typeof value === 'string') return value.replaceAll(new URL(`${root}/`, 'file://').href, './');
	if (Array.isArray(value)) return value.map((entry) => portable(entry, root));
	if (value !== null && typeof value === 'object') {
		return Object.fromEntries(
			Object.entries(value).map(([key, entry]) => [
				String(portable(key, root)),
				portable(entry, root),
			]),
		);
	}
	return value;
}

/** A stable heading anchor belongs to an import subpath, including its root entry. */
function anchor(key: string): string {
	return key === '.' ? 'root' : key.slice(2).replaceAll('/', '-');
}

/** Render text as output notation, preserving nested code examples literally. */
function output(value: string): string {
	const longest = Math.max(3, ...[...value.matchAll(/`+/gu)].map((match) => match[0].length));
	const fence = '`'.repeat(longest + 1);
	// Native output prefixes example lines with spaces but preserves their source
	// tabs. Normalize display indentation only; JSON retains the original comments.
	const text = value.trim().split('\n').map((line) =>
		line.replace(/[\t ]+$/u, '').replace(/^[\t ]+/u, (indent) => indent.replaceAll('\t', '  '))
	).join('\n');
	return `${fence}text\n${text}\n${fence}\n`;
}

/** Manifest text is data, including when it becomes an HTML label or URL. */
function html(value: string): string {
	return value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;')
		.replaceAll('"', '&quot;').replaceAll("'", '&#39;');
}

/** Add a useful entry page to Deno's otherwise empty multi-module overview. */
async function overview(root: string, members: readonly MemberType[]): Promise<void> {
	const directory = `${root}/.artifacts/docs/html`;
	await Deno.copyFile(`${directory}/index.html`, `${directory}/modules.html`);
	let sections = '';
	for (const { directory: name, manifest } of members) {
		sections += `<section><h2>${html(manifest.name)}</h2><ul>`;
		for (const [key, source] of Object.entries(manifest.exports).sort(([left], [right]) => left.localeCompare(right))) {
			const target = `${name}/${source.slice(2)}/index.html`;
			await Deno.stat(`${directory}/${target}`);
			const specifier = manifest.name + (key === '.' ? '' : key.slice(1));
			sections += `<li><a href="${html(target)}"><code>${html(specifier)}</code></a></li>`;
		}
		sections += '</ul></section>';
	}
	await Deno.writeTextFile(
		`${directory}/index.html`,
		`<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1">
<title>Public package contracts · @okikio/utils</title>
<style>body{font:16px/1.6 system-ui,sans-serif;color:#182031;max-width:1050px;margin:32px auto;padding:0 24px}
a{color:#0969da}code{font-size:.9em;overflow-wrap:anywhere}.packages{display:grid;grid-template-columns:repeat(auto-fit,minmax(260px,1fr));gap:20px}
section{border:1px solid #d0d7de;border-radius:8px;padding:16px}h2{font-size:20px;margin:0}ul{padding-left:20px}li{margin:6px 0}</style></head>
<body><h1>Public package contracts</h1><p>Choose a package and its public import path. Each module page explains its functions,
types, fields and methods. Type parameters and linked declarations show how input and result types fit together.</p>
<p>The installation facade uses the same contracts through <code>@okikio/utils/&lt;package&gt;</code> imports.
The module pages' usage blocks use source filenames; the links below give the application import paths.</p>
<p><a href="modules.html">Open the native symbol overview and search</a>.</p>
<main class="packages">${sections}</main></body></html>\n`,
	);
}

/** Publish one complete deterministic file, or report drift without mutation. */
async function publish(path: string, text: string, check: boolean): Promise<void> {
	// Authored prose is untouched. The repository formatter owns generated Markdown/JSON.
	const extension = path.endsWith('.json') ? 'json' : 'md';
	const formatter = new Deno.Command(Deno.execPath(), {
		args: ['fmt', '--ext', extension, '-'],
		stdin: 'piped',
		stdout: 'piped',
		stderr: 'piped',
	}).spawn();
	const writer = formatter.stdin.getWriter();
	await writer.write(new TextEncoder().encode(text));
	await writer.close();
	const formatted = await formatter.output();
	if (!formatted.success) throw new Error(new TextDecoder().decode(formatted.stderr));
	const contents = new TextDecoder().decode(formatted.stdout);
	if (check) {
		const previous = await Deno.readTextFile(path).catch((error: unknown) => {
			if (error instanceof Deno.errors.NotFound) return '';
			throw error;
		});
		if (previous !== contents) throw new Error(`Contract reference needs regeneration: ${path}`);
	} else await Deno.writeTextFile(path, contents);
}

/** Generate all focused references and a facade index from current manifests. */
async function build(mode: string): Promise<void> {
	if (!['write', 'check', 'html'].includes(mode)) throw new TypeError('Use write, check or html.');
	const root = fileURLToPath(new URL('../', import.meta.url)).replace(/\/$/u, '');
	const members: MemberType[] = [];
	for await (const entry of Deno.readDir(`${root}/packages`)) {
		if (!entry.isDirectory) continue;
		const manifest = member(parse(await Deno.readTextFile(`${root}/packages/${entry.name}/deno.jsonc`)));
		members.push({ directory: entry.name, manifest });
	}
	members.sort((left, right) => left.directory.localeCompare(right.directory));
	const focused = members.filter((member) => member.directory !== 'utils');
	const files = [
		...new Set(
			focused.flatMap(({ directory, manifest }) =>
				Object.values(manifest.exports).map((path) => resolve(root, 'packages', directory, path))
			),
		),
	].sort();
	if (mode === 'html') {
		await Deno.mkdir(`${root}/.artifacts/docs`, { recursive: true });
		await doc(['--html', '--name', '@okikio/utils contracts', '--output', `${root}/.artifacts/docs/html`, ...files]);
		await overview(root, focused);
		console.log('Wrote browsable contracts to .artifacts/docs/html/index.html.');
		return;
	}
	const graph = JSON.parse(await doc(['--json', ...files])) as DocumentType;
	const terminal = await doc(files);
	const rendered = new Map<string, string>();
	let current: string | undefined;
	for (const line of terminal.split('\n')) {
		if (line.startsWith('file://') && files.includes(fileURLToPath(line))) {
			current = line;
			rendered.set(current, '');
		} else if (current !== undefined) rendered.set(current, `${rendered.get(current)}${line}\n`);
	}
	let symbols = 0;
	for (const { directory, manifest } of focused) {
		const entries = Object.entries(manifest.exports).sort(([left], [right]) => left.localeCompare(right));
		const packageRoot = `${root}/packages/${directory}`;
		let markdown = `# ${manifest.name} contracts\n\n` +
			`[Start with the examples](README.md). This generated reference lists every public import path, ` +
			`then prints its exported functions, types, fields and declaration explanations.\n\n` +
			`The blocks use Deno's documentation notation, not implementation code to paste into an application. ` +
			`The [structured contracts](API.json) preserve the full renderer model, including overloads, method ` +
			`type parameters and documentation tags. The linked source defines runtime behavior; the guide explains ` +
			`ownership, cancellation, defaults and use cases. Supporting private types can appear in the renderer model; ` +
			`their presence does not make them public imports.\n\n` +
			`Regenerate with \`deno task docs:api\`; verify with \`deno task docs:api:check\`. ` +
			`For a searchable HTML reference, run \`deno task docs:html\`.\n\n` +
			`## Public imports\n\n| Import | Source | Reference |\n| --- | --- | --- |\n`;
		const modules: Record<string, unknown> = {};
		for (const [key, path] of entries) {
			const name = manifest.name + (key === '.' ? '' : key.slice(1));
			markdown += `| \`${name}\` | [${path}](${path}) | [${anchor(key)}](#${anchor(key)}) |\n`;
		}
		for (const [key, path] of entries) {
			const name = manifest.name + (key === '.' ? '' : key.slice(1));
			const url = new URL(path, new URL(`${packageRoot}/`, 'file://')).href;
			const model = graph.nodes[url];
			const text = rendered.get(url);
			if (model === undefined || text === undefined) throw new Error(`Renderer omitted public module ${name}.`);
			modules[name] = portable(model, root);
			symbols += model.symbols.length;
			markdown += `\n## ${anchor(key)}\n\nImport \`${name}\`. [Source](${path}).\n\n`;
			const blocks = text.split(/(?=^Defined in )/mu);
			if (blocks[0]?.trim()) {
				const module = model as typeof model & { readonly module_doc?: { readonly doc?: string } };
				markdown += `${module.module_doc?.doc ?? ''}\n`;
				blocks.shift();
			}
			if (model.imports?.length) {
				markdown += '\nImported bindings connect this module to the contracts below. A local source link can name an ' +
					'internal module; use the public import table when writing application imports.\n\n' +
					'| Imported binding | Contract owner or source |\n| --- | --- |\n';
				for (const imported of model.imports) {
					let target: string;
					if (imported.src.startsWith(new URL(`${root}/packages/`, 'file://').href)) {
						const path = fileURLToPath(imported.src);
						const owner = relative(`${root}/packages`, path).split('/')[0]!;
						target = owner === directory
							? `[Source](${relative(packageRoot, path)})`
							: `[${owner} contracts](${relative(packageRoot, `${root}/packages/${owner}/API.md`)})`;
					} else if (
						imported.src.startsWith('https:') || imported.src.startsWith('npm:') || imported.src.startsWith('jsr:')
					) {
						target = imported.src.startsWith('https:') ? `[External source](${imported.src})` : `\`${imported.src}\``;
					} else {
						target = `External declaration: \`${String(portable(imported.src, root)).split('node_modules/').at(-1)}\``;
					}
					markdown += `| \`${imported.importedName ?? '(side effect)'}\` | ${target} |\n`;
				}
			}
			const headings = new Set<string>();
			for (const block of blocks) {
				const match = /^Defined in (file:\/\/.*):(\d+):(\d+)\n+/u.exec(block);
				if (match === null) {
					if (block.trim()) throw new Error(`Unrecognized declaration output in ${name}.`);
					continue;
				}
				const source = relative(packageRoot, fileURLToPath(match[1]!));
				const body = String(portable(block.slice(match[0].length).trim(), root));
				const symbol =
					/^(?:(?:async|abstract) )?(?:function|class|interface|type|const|let|var|namespace|reference) ([\w$]+)/u
						.exec(body)?.[1];
				if (symbol !== undefined && !headings.has(symbol)) {
					markdown += `### ${anchor(key)}: ${symbol}\n\n`;
					headings.add(symbol);
				}
				const location = source.includes('node_modules/')
					? `External declaration: \`${source.split('node_modules/').at(-1)}\`, line ${match[2]}.`
					: `[Declaration source](${source}#L${match[2]})`;
				markdown += `${location}\n\n${output(body)}\n`;
			}
		}
		await publish(`${packageRoot}/API.md`, markdown, mode === 'check');
		await publish(
			`${packageRoot}/API.json`,
			JSON.stringify(
				{
					package: manifest.name,
					packageVersion: manifest.version,
					rendererVersion: graph.version,
					modules,
				},
				null,
				2,
			),
			mode === 'check',
		);
	}
	const facade = members.find((member) => member.directory === 'utils');
	if (facade === undefined) throw new Error('Missing utils facade.');
	let index = '# Public package contracts\n\n' +
		'Begin with a package guide for a working example. Its generated reference exposes every public subpath and ' +
		'the types, fields, functions and comments behind it. Structured JSON retains Deno’s complete declaration model. ' +
		'Local source locations in JSON are relative to the repository root.\n\n' +
		'| Package | Examples | Contract reference | Structured contracts |\n| --- | --- | --- | --- |\n';
	for (const { directory, manifest } of focused) {
		index += `| \`${manifest.name}\` | [Guide](../packages/${directory}/README.md) | ` +
			`[Reference](../packages/${directory}/API.md) | [JSON](../packages/${directory}/API.json) |\n`;
	}
	index += '\n## Keep the references current\n\n' +
		'`deno task docs:api` derives these files from package manifests and [deno doc](https://docs.deno.com/runtime/reference/cli/doc/); ' +
		'`deno task docs:api:check` detects drift without changing files. Both commands use the installed Deno version. ' +
		'Run `mise install` and `mise run install` first when preparing this checkout.\n\n' +
		'`deno task docs:html` also generates a searchable static reference in `.artifacts/docs/html/`. ' +
		'Open its `index.html` in a browser. Generation does not publish a website.\n\n' +
		'The Markdown blocks are Deno’s readable notation, so an interface field has its explanation immediately below it. ' +
		'Use JSON or the declaration source when you need the complete type structure rather than the display notation. ' +
		'In a JSON file, select `modules["@okikio/activity"].symbols`, for example, to inspect the exported activity declarations.\n\n' +
		'Runtime validation still uses the supplied schemas. A TypeScript declaration alone does not validate a value ' +
		'from a request or persisted record, and generating documentation does not change the runtime’s contracts.\n';
	await publish(`${root}/docs/contracts.md`, index, mode === 'check');
	let umbrella = '# @okikio/utils contracts\n\n' +
		'This installation facade re-exports focused packages. Read the owning package’s reference for the full types, ' +
		'fields and behavior explanations; the facade does not maintain a second implementation. ' +
		'Its root and `/all` entries collect package namespaces.\n\n' +
		'| Facade import | Owning contract reference |\n| --- | --- |\n';
	for (const [key] of Object.entries(facade.manifest.exports).sort(([left], [right]) => left.localeCompare(right))) {
		const suffix = key.slice(2);
		const [owner, ...subpath] = suffix.split('/');
		const member = focused.find(({ directory }) => directory === owner);
		const target = member === undefined
			? '../../docs/contracts.md'
			: `../${owner}/API.md#${anchor(subpath.length ? `./${subpath.join('/')}` : '.')}`;
		umbrella += `| \`${facade.manifest.name}${key === '.' ? '' : key.slice(1)}\` | [Reference](${target}) |\n`;
	}
	await publish(`${root}/packages/utils/API.md`, umbrella, mode === 'check');
	console.log(
		`${mode}: ${focused.length} focused packages, ${files.length} modules, ${symbols} documented symbol entries.`,
	);
}

if (import.meta.main) await build(Deno.args[0] ?? 'write');
